'use client';

import { useEffect, useRef, useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  hold,
  PRESS_LEAD_MS,
  pressedQuietOf,
  pressedSolidOf,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { MicIcon, PhoneOffIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { penOf, tokenOf, watchTheme } from './_parts/canvas';
import { followLevel } from './_parts/level';
import {
  createField,
  drawField,
  geometryOf,
  levelOf,
  settleField,
  stepField,
  stillFrameOf,
  type FieldFrame,
  type FieldPalette,
  type ParticleField,
} from './_parts/particle-field';
import { usePlayWhileSeen } from './_parts/use-play-while-seen';
import {
  easeWeights,
  oneHotOf,
  VOICE_STATE_LABELS,
  VOICE_STATE_WORD,
  type StateTable,
  type VoiceState,
} from './_parts/voice-state';

export type { VoiceState } from './_parts/voice-state';

const STATE_EASE_S = 0.25;

/** A frame is skipped when the last one is younger than this: the sphere never draws above about 66 frames a second. */
const MIN_FRAME_MS = 15;

/** A long stall (a tab that was hidden) moves the springs by this much at most. */
const MAX_STEP_S = 0.05;

function paletteOf(canvas: HTMLCanvasElement): FieldPalette {
  return {
    primary: tokenOf(canvas, '--primary'),
    foreground: tokenOf(canvas, '--foreground'),
  };
}

function fieldOf(holder: { current: ParticleField | null }) {
  if (holder.current === null) {
    holder.current = createField();
  }
  return holder.current;
}

export type ParticleOrbProps = {
  state: VoiceState;
  /** The live level of the voice, between 0 and 1. Left out, a simulated voice drives the sphere. */
  level?: () => number;
  size?: number;
  className?: string;
};

export function ParticleOrb({
  state,
  level,
  size = 200,
  className,
}: ParticleOrbProps) {
  const { ref: canvasRef, isPlaying } = usePlayWhileSeen<HTMLCanvasElement>();
  const stateRef = useRef(state);
  const levelRef = useRef(level);
  const fieldRef = useRef<ParticleField | null>(null);

  useEffect(() => {
    stateRef.current = state;
    levelRef.current = level;
  }, [state, level]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || isPlaying) {
      return;
    }
    const pen = penOf(canvas, size);
    if (!pen) {
      return;
    }
    const surface: HTMLCanvasElement = canvas;
    const context: CanvasRenderingContext2D = pen;
    const field = fieldOf(fieldRef);
    const geometry = geometryOf(size);
    const frame = stillFrameOf(state);

    function drawStill() {
      const palette = paletteOf(surface);
      drawField(context, geometry, field, frame, palette);
    }

    settleField(field, frame);
    drawStill();
    return watchTheme(drawStill);
  }, [canvasRef, isPlaying, state, size]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !isPlaying) {
      return;
    }
    const pen = penOf(canvas, size);
    if (!pen) {
      return;
    }
    const surface: HTMLCanvasElement = canvas;
    const context: CanvasRenderingContext2D = pen;
    const field = fieldOf(fieldRef);
    const geometry = geometryOf(size);
    const weights: StateTable = oneHotOf(stateRef.current);
    const frame: FieldFrame = { weights, level: 0, seconds: 0 };
    let palette = paletteOf(surface);
    const stopWatching = watchTheme(() => {
      palette = paletteOf(surface);
    });
    const startedAt = performance.now();
    let last = startedAt;
    let handle = 0;

    function draw(now: number) {
      handle = requestAnimationFrame(draw);
      const sinceLast = now - last;
      if (sinceLast < MIN_FRAME_MS) {
        return;
      }
      last = now;
      const step = Math.min(MAX_STEP_S, sinceLast / 1000);
      const elapsed = now - startedAt;
      const stateEase = 1 - Math.exp(-step / STATE_EASE_S);
      easeWeights(weights, oneHotOf(stateRef.current), stateEase);
      const target = levelOf(levelRef.current, weights, elapsed);
      frame.level = followLevel(frame.level, target, step);
      frame.seconds = elapsed / 1000;
      stepField(field, frame, step);
      drawField(context, geometry, field, frame, palette);
    }

    handle = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(handle);
      stopWatching();
    };
  }, [canvasRef, isPlaying, size]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden='true'
      style={{ width: size, height: size }}
      className={cn('block', className)}
    />
  );
}

type CallKey = {
  key: 'start' | 'end';
  label: string;
  icon: React.ReactNode;
  variant: 'default' | 'outline';
};

function callKeyOf(isCalling: boolean): CallKey {
  if (isCalling) {
    return {
      key: 'end',
      label: 'End call',
      icon: <PhoneOffIcon />,
      variant: 'outline',
    };
  }
  return {
    key: 'start',
    label: 'Start talking',
    icon: <MicIcon />,
    variant: 'default',
  };
}

function pressClassOf(isCalling: boolean, isPressed: boolean) {
  if (isCalling) {
    return pressedQuietOf(isPressed);
  }
  return pressedSolidOf(isPressed);
}

const TURN_MS: StateTable = {
  idle: 0,
  listening: 2800,
  thinking: 1900,
  speaking: 3200,
};

const NEXT_STATE: Record<VoiceState, VoiceState> = {
  idle: 'idle',
  listening: 'thinking',
  thinking: 'speaking',
  speaking: 'listening',
};

/** Listens, thinks and speaks once, then listens again before the demonstration ends the call. */
const CALL_MS = 9300;

export default function Voice04() {
  const [state, setState] = useState<VoiceState>('idle');
  const { pressed, press } = usePress<'call'>();
  const isTabVisible = useDocumentVisible();
  const isCalling = state !== 'idle';
  const key = callKeyOf(isCalling);

  function startCall() {
    setState('listening');
  }

  function endCall() {
    setState('idle');
  }

  function toggleCall() {
    if (isCalling) {
      endCall();
      return;
    }
    startCall();
  }

  const steps: AutoplayStep[] = [
    { after: 1500, run: () => press('call') },
    { after: PRESS_LEAD_MS, run: startCall },
    { after: CALL_MS, run: () => press('call') },
    { after: PRESS_LEAD_MS, run: endCall },
    { after: 2200, run: hold },
  ];
  const { ref, isInView, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 700,
    onReset: endCall,
  });
  const isOnScreen = isInView && isTabVisible;

  useEffect(() => {
    if (!isCalling || !isOnScreen) {
      return;
    }
    function nextTurn() {
      setState(NEXT_STATE[state]);
    }

    const timer = setTimeout(nextTurn, TURN_MS[state]);
    return () => clearTimeout(timer);
  }, [state, isCalling, isOnScreen]);

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='flex w-full max-w-[22rem] flex-col items-center gap-4'
    >
      <div className='bg-card hairline-ring ring-border flex w-full flex-col items-center gap-3 rounded-xl px-4 pt-6 pb-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <ParticleOrb state={state} />
        <div className='flex flex-col items-center gap-0.5'>
          <p className='text-sm font-medium'>
            <WordRoll
              text={VOICE_STATE_WORD[state]}
              labels={VOICE_STATE_LABELS}
            />
          </p>
          <p className='text-muted-foreground text-xs'>Simulated voice</p>
        </div>
        <Button
          type='button'
          variant={key.variant}
          onClick={toggleCall}
          className={pressClassOf(isCalling, pressed === 'call')}
        >
          <AnimatedSize
            as='span'
            axis='width'
            contentClassName='flex items-center'
          >
            <Swap swapKey={key.key}>
              <span className='flex items-center gap-1.5'>
                {key.icon}
                {key.label}
              </span>
            </Swap>
          </AnimatedSize>
        </Button>
      </div>
      <LiveRegion
        message={spokenUnless(isAutoplaying, VOICE_STATE_WORD[state])}
      />
    </div>
  );
}

/** A backing store above two device pixels a point costs four times the fill for a picture nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

export function pixelRatioOf() {
  const screenRatio = window.devicePixelRatio || 1;
  return Math.min(screenRatio, MAX_PIXEL_RATIO);
}

export function penOf(canvas: HTMLCanvasElement, size: number) {
  const ratio = pixelRatioOf();
  const pixels = Math.round(size * ratio);
  if (canvas.width !== pixels) {
    canvas.width = pixels;
    canvas.height = pixels;
  }
  const pen = canvas.getContext('2d');
  pen?.setTransform(ratio, 0, 0, ratio, 0, 0);
  return pen;
}

export function tokenOf(element: Element, token: string) {
  const styles = getComputedStyle(element);
  const value = styles.getPropertyValue(token).trim();
  return value || styles.color;
}

/** A canvas holds the colours it was drawn with: it is told when the theme of the page changes. */
export function watchTheme(onChange: () => void) {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class', 'style', 'data-theme'],
  });
  return () => observer.disconnect();
}

const ATTACK_S = 0.04;

const RELEASE_S = 0.2;

/** Rises fast and falls slowly, whatever the frame rate. */
export function followLevel(current: number, target: number, step: number) {
  const gap = target - current;
  const isRising = gap > 0;
  let constant = RELEASE_S;
  if (isRising) {
    constant = ATTACK_S;
  }
  const amount = 1 - Math.exp(-step / constant);
  return current + gap * amount;
}

import { noiseAt, speechLevelAt } from '@/registry/ndeko/lib/speech-envelope';

import {
  blendOf,
  oneHotOf,
  type StateTable,
  type VoiceState,
} from './voice-state';

const TAU = Math.PI * 2;

export const PARTICLE_COUNT = 340;

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));

/** Radius of the sphere, as a share of the canvas: the voice pushes particles out to 1.6 times that, and the pulse of speech adds 7% more, so the edge of the canvas is never reached. */
const RADIUS_SHARE = 0.26;

const MIN_DOT = 0.0036;

const DOT_RANGE = 0.0062;

const MIN_SPIN = 0.6;

const SPIN_RANGE = 0.8;

/** Each particle falls back on its own spring, so a surge does not return as one block. */
const MIN_STIFFNESS = 260;

const STIFFNESS_RANGE = 440;

const DAMPING = 17;

const MIN_REACH = 0.3;

const REACH_RANGE = 0.7;

const MIN_PUSH = -0.2;

const MAX_PUSH = 0.6;

const DEPTH = 0.3;

const TILT = 0.42;

const ALPHA_BUCKETS = 6;

const MIN_ALPHA = 0.16;

const MAX_ALPHA = 0.8;

const SPIN_SPEED: StateTable = {
  idle: 0.14,
  listening: 0.24,
  thinking: 1.3,
  speaking: 0.32,
};

const REACH: StateTable = {
  idle: 0,
  listening: 0.8,
  thinking: 0,
  speaking: 0.5,
};

const BRIGHTNESS: StateTable = {
  idle: 0.55,
  listening: 0.8,
  thinking: 0.9,
  speaking: 1,
};

const TIGHTEN = 0.18;

const PULSE = 0.07;

const BREATH_HERTZ = 0.2;

const BREATH_DEPTH = 0.035;

const THINKING_INK = 0.35;

const LISTEN_SEED = 0.4;

const SPEAK_SEED = 2.2;

const STILL_LEVEL = 0.6;

const STILL_SECONDS = 0.4;

const STILL_TURN = 0.5;

type Particle = {
  x: number;
  y: number;
  z: number;
  dot: number;
  spin: number;
  reach: number;
  stiffness: number;
};

function particleAt(index: number): Particle {
  const share = (index + 0.5) / PARTICLE_COUNT;
  const y = 1 - 2 * share;
  const ring = Math.sqrt(1 - y * y);
  const angle = index * GOLDEN_ANGLE;
  return {
    x: Math.cos(angle) * ring,
    y,
    z: Math.sin(angle) * ring,
    dot: MIN_DOT + noiseAt(index, 1.7) * DOT_RANGE,
    spin: MIN_SPIN + noiseAt(index, 5.1) * SPIN_RANGE,
    reach: MIN_REACH + noiseAt(index, 9.3) * REACH_RANGE,
    stiffness: MIN_STIFFNESS + noiseAt(index, 2.9) * STIFFNESS_RANGE,
  };
}

const PARTICLES: readonly Particle[] = Array.from(
  { length: PARTICLE_COUNT },
  (_, index) => particleAt(index)
);

export type ParticleField = {
  turns: Float32Array;
  pushes: Float32Array;
  speeds: Float32Array;
  xs: Float32Array;
  ys: Float32Array;
  radii: Float32Array;
  buckets: Uint8Array;
};

export function createField(): ParticleField {
  return {
    turns: new Float32Array(PARTICLE_COUNT),
    pushes: new Float32Array(PARTICLE_COUNT),
    speeds: new Float32Array(PARTICLE_COUNT),
    xs: new Float32Array(PARTICLE_COUNT),
    ys: new Float32Array(PARTICLE_COUNT),
    radii: new Float32Array(PARTICLE_COUNT),
    buckets: new Uint8Array(PARTICLE_COUNT),
  };
}

export type FieldFrame = {
  weights: StateTable;
  level: number;
  seconds: number;
};

export type FieldGeometry = {
  size: number;
  centre: number;
  radius: number;
};

export type FieldPalette = {
  primary: string;
  foreground: string;
};

export function geometryOf(size: number): FieldGeometry {
  return { size, centre: size / 2, radius: size * RADIUS_SHARE };
}

export function stillFrameOf(state: VoiceState): FieldFrame {
  return {
    weights: oneHotOf(state),
    level: STILL_LEVEL,
    seconds: STILL_SECONDS,
  };
}

export function levelOf(
  provider: (() => number) | undefined,
  weights: StateTable,
  elapsed: number
) {
  if (provider) {
    return provider();
  }
  const heard = speechLevelAt(elapsed, LISTEN_SEED);
  const spoken = speechLevelAt(elapsed, SPEAK_SEED);
  return weights.listening * heard + weights.speaking * spoken;
}

function reachOf(frame: FieldFrame) {
  const share = blendOf(REACH, frame.weights);
  return share * frame.level;
}

function scaleOf(frame: FieldFrame) {
  const breathAngle = frame.seconds * TAU * BREATH_HERTZ;
  const breath = Math.sin(breathAngle) * BREATH_DEPTH;
  const tightened = frame.weights.thinking * TIGHTEN;
  const calmBreath = frame.weights.idle * breath;
  const pulse = frame.weights.speaking * frame.level * PULSE;
  return 1 - tightened + calmBreath + pulse;
}

function inkOf(weights: StateTable) {
  const thinking = weights.thinking * THINKING_INK;
  return Math.min(1, weights.speaking + thinking);
}

export function stepField(
  field: ParticleField,
  frame: FieldFrame,
  step: number
) {
  const spin = blendOf(SPIN_SPEED, frame.weights);
  const reach = reachOf(frame);
  for (let index = 0; index < PARTICLE_COUNT; index += 1) {
    const particle = PARTICLES[index];
    field.turns[index] += spin * particle.spin * step;
    const target = reach * particle.reach;
    const pull = particle.stiffness * (target - field.pushes[index]);
    const drag = DAMPING * field.speeds[index];
    field.speeds[index] += (pull - drag) * step;
    field.pushes[index] += field.speeds[index] * step;
  }
}

export function settleField(field: ParticleField, frame: FieldFrame) {
  const reach = reachOf(frame);
  for (let index = 0; index < PARTICLE_COUNT; index += 1) {
    const particle = PARTICLES[index];
    field.turns[index] = STILL_TURN * particle.spin;
    field.pushes[index] = reach * particle.reach;
    field.speeds[index] = 0;
  }
}

function boundedPush(push: number) {
  return Math.min(MAX_PUSH, Math.max(MIN_PUSH, push));
}

function bucketOf(depth: number) {
  const share = (depth + 1) / 2;
  const bucket = Math.floor(share * ALPHA_BUCKETS);
  return Math.min(ALPHA_BUCKETS - 1, bucket);
}

const COS_TILT = Math.cos(TILT);

const SIN_TILT = Math.sin(TILT);

function projectField(
  field: ParticleField,
  geometry: FieldGeometry,
  frame: FieldFrame
) {
  const base = geometry.radius * scaleOf(frame);
  for (let index = 0; index < PARTICLE_COUNT; index += 1) {
    const particle = PARTICLES[index];
    const cos = Math.cos(field.turns[index]);
    const sin = Math.sin(field.turns[index]);
    const turnedX = particle.x * cos + particle.z * sin;
    const turnedZ = particle.z * cos - particle.x * sin;
    const tiltedY = particle.y * COS_TILT - turnedZ * SIN_TILT;
    const tiltedZ = particle.y * SIN_TILT + turnedZ * COS_TILT;
    const push = boundedPush(field.pushes[index]);
    const reach = base * (1 + push);
    const lens = 1 / (1 - tiltedZ * DEPTH);
    field.xs[index] = geometry.centre + turnedX * reach * lens;
    field.ys[index] = geometry.centre + tiltedY * reach * lens;
    field.radii[index] = particle.dot * geometry.size * lens;
    field.buckets[index] = bucketOf(tiltedZ);
  }
}

function alphaOfBucket(bucket: number) {
  const share = (bucket + 0.5) / ALPHA_BUCKETS;
  return MIN_ALPHA + share * (MAX_ALPHA - MIN_ALPHA);
}

/** Every dot of one depth in one path, so a few hundred dots cost a few fills. */
function fillBucket(
  context: CanvasRenderingContext2D,
  field: ParticleField,
  bucket: number,
  alpha: number,
  color: string
) {
  if (alpha < 0.01) {
    return;
  }
  context.globalAlpha = alpha;
  context.fillStyle = color;
  context.beginPath();
  for (let index = 0; index < PARTICLE_COUNT; index += 1) {
    if (field.buckets[index] !== bucket) {
      continue;
    }
    const radius = field.radii[index];
    context.moveTo(field.xs[index] + radius, field.ys[index]);
    context.arc(field.xs[index], field.ys[index], radius, 0, TAU);
  }
  context.fill();
}

/** Neutral while the sphere listens, in the brand colour while the agent speaks; nearer dots are stronger. */
export function drawField(
  context: CanvasRenderingContext2D,
  geometry: FieldGeometry,
  field: ParticleField,
  frame: FieldFrame,
  palette: FieldPalette
) {
  context.clearRect(0, 0, geometry.size, geometry.size);
  projectField(field, geometry, frame);
  const brightness = blendOf(BRIGHTNESS, frame.weights);
  const ink = inkOf(frame.weights);
  for (let bucket = 0; bucket < ALPHA_BUCKETS; bucket += 1) {
    const alpha = alphaOfBucket(bucket) * brightness;
    fillBucket(context, field, bucket, alpha * (1 - ink), palette.foreground);
    fillBucket(context, field, bucket, alpha * ink, palette.primary);
  }
}

'use client';

import { useInView } from 'motion/react';
import { useRef } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const IN_VIEW_SHARE = 0.2;

/**
 * A voice indicator moves only while someone can see it: on screen, in the tab that is shown,
 * without reduced motion. `isStill` asks for the still frame instead, and `isOnScreen` is for the
 * clocks that keep a session going under reduced motion.
 */
export function usePlayWhileSeen<Element extends HTMLElement = HTMLElement>() {
  const ref = useRef<Element>(null);
  const isInView = useInView(ref, { amount: IN_VIEW_SHARE });
  const isTabVisible = useDocumentVisible();
  const isStill = usePrefersReducedMotion();
  const isOnScreen = isInView && isTabVisible;
  const isPlaying = isOnScreen && !isStill;

  return { ref, isOnScreen, isPlaying, isStill };
}

export type VoiceState = 'idle' | 'listening' | 'thinking' | 'speaking';

export const VOICE_STATES: readonly VoiceState[] = [
  'idle',
  'listening',
  'thinking',
  'speaking',
];

export const VOICE_STATE_WORD: Record<VoiceState, string> = {
  idle: 'Idle',
  listening: 'Listening',
  thinking: 'Thinking',
  speaking: 'Speaking',
};

export const VOICE_STATE_LABELS = VOICE_STATES.map(
  (state) => VOICE_STATE_WORD[state]
);

export type StateTable = Record<VoiceState, number>;

export function oneHotOf(state: VoiceState): StateTable {
  return {
    idle: Number(state === 'idle'),
    listening: Number(state === 'listening'),
    thinking: Number(state === 'thinking'),
    speaking: Number(state === 'speaking'),
  };
}

export function easeWeights(
  weights: StateTable,
  target: StateTable,
  amount: number
) {
  for (const state of VOICE_STATES) {
    const gap = target[state] - weights[state];
    weights[state] += gap * amount;
  }
}

export function blendOf(values: StateTable, weights: StateTable) {
  let total = 0;
  for (const state of VOICE_STATES) {
    total += values[state] * weights[state];
  }
  return total;
}
